<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Offer\Action\Query;

use Module\Offer\Action\Dto\Admin\ListParamDto;
use Module\Offer\Action\Dto\Admin\OfferShortDto;
use Module\Offer\Action\Query\AdminGetOfferListQry;
use Module\Offer\Model\Offer;
use Module\Offer\Model\OfferRepository;
use Module\Product\Action\Query\JoinProductByIdDqlQry;
use Module\Product\Model\Product;
use Module\Product\Model\ProductRepository;
use Module\Store\Action\Query\JoinStoreByIdDqlQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class AdminGetOfferListQryTest extends IntegrationTestCase
{
    private AdminGetOfferListQry $sut;

    private OfferRepository $offerRepository;
    private ProductRepository $productRepository;
    private StoreRepository $storeRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->offerRepository = $this->container->get(OfferRepository::class);
        $this->productRepository = $this->container->get(ProductRepository::class);
        $this->storeRepository = $this->container->get(StoreRepository::class);

        $this->sut = new AdminGetOfferListQry(
            $this->container->get(JoinProductByIdDqlQry::class),
            $this->container->get(JoinStoreByIdDqlQry::class),
            $this->offerRepository->getEntityManager(),
        );

        $this->prepareDb();
    }

    /**
     * @param OfferShortDto[] $expectedItems
     */
    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        ?string $search,
        ?int $storeId,
        ?int $page,
        ?int $perPage,
        array $expectedItems,
        int $expectedPage,
        int $expectedPerPage,
    ): void {
        $result = $this->sut->handle(new ListParamDto($search, $storeId, $page, $perPage));

        $this->assertEquals($expectedItems, $result->items);
        $this->assertSame($expectedPage, $result->page);
        $this->assertSame($expectedPerPage, $result->perPage);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'no filters returns all items ordered by store name then product name' => [
                'search' => null,
                'storeId' => null,
                'page' => 1,
                'perPage' => 10,
                'expectedItems' => [
                    new OfferShortDto(801, 'Alpha Store', false, 'ean-2', 'Blue circle', 1200),
                    new OfferShortDto(800, 'Alpha Store', true, 'ean-1', 'Custom Name', 1000),
                    new OfferShortDto(802, 'Beta Store', true, 'ean-3', '', 800),
                    new OfferShortDto(803, 'Beta Store', true, 'ean-1', 'Red square', 900),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
            'default page and perPage' => [
                'search' => null,
                'storeId' => null,
                'page' => null,
                'perPage' => null,
                'expectedItems' => [
                    new OfferShortDto(801, 'Alpha Store', false, 'ean-2', 'Blue circle', 1200),
                    new OfferShortDto(800, 'Alpha Store', true, 'ean-1', 'Custom Name', 1000),
                    new OfferShortDto(802, 'Beta Store', true, 'ean-3', '', 800),
                    new OfferShortDto(803, 'Beta Store', true, 'ean-1', 'Red square', 900),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
            'perPage limits results' => [
                'search' => null,
                'storeId' => null,
                'page' => 1,
                'perPage' => 2,
                'expectedItems' => [
                    new OfferShortDto(801, 'Alpha Store', false, 'ean-2', 'Blue circle', 1200),
                    new OfferShortDto(800, 'Alpha Store', true, 'ean-1', 'Custom Name', 1000),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 2,
            ],
            'second page' => [
                'search' => null,
                'storeId' => null,
                'page' => 2,
                'perPage' => 2,
                'expectedItems' => [
                    new OfferShortDto(802, 'Beta Store', true, 'ean-3', '', 800),
                    new OfferShortDto(803, 'Beta Store', true, 'ean-1', 'Red square', 900),
                ],
                'expectedPage' => 2,
                'expectedPerPage' => 2,
            ],
            'page beyond results returns empty' => [
                'search' => null,
                'storeId' => null,
                'page' => 3,
                'perPage' => 2,
                'expectedItems' => [],
                'expectedPage' => 3,
                'expectedPerPage' => 2,
            ],
            'filter by storeId' => [
                'search' => null,
                'storeId' => 20,
                'page' => 1,
                'perPage' => 10,
                'expectedItems' => [
                    new OfferShortDto(801, 'Alpha Store', false, 'ean-2', 'Blue circle', 1200),
                    new OfferShortDto(800, 'Alpha Store', true, 'ean-1', 'Custom Name', 1000),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
            'search by offer productName' => [
                'search' => 'Custom',
                'storeId' => null,
                'page' => 1,
                'perPage' => 10,
                'expectedItems' => [
                    new OfferShortDto(800, 'Alpha Store', true, 'ean-1', 'Custom Name', 1000),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
            'search by product name via join' => [
                'search' => 'Red',
                'storeId' => null,
                'page' => 1,
                'perPage' => 10,
                'expectedItems' => [
                    new OfferShortDto(803, 'Beta Store', true, 'ean-1', 'Red square', 900),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
            'search by productEan' => [
                'search' => 'ean-2',
                'storeId' => null,
                'page' => 1,
                'perPage' => 10,
                'expectedItems' => [
                    new OfferShortDto(801, 'Alpha Store', false, 'ean-2', 'Blue circle', 1200),
                ],
                'expectedPage' => 1,
                'expectedPerPage' => 10,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->storeRepository->saveWithId(Store::factory('STR-20', 'Alpha Store', 'Alpha Address', 20));
        $this->storeRepository->saveWithId(Store::factory('STR-21', 'Beta Store', 'Beta Address', 21));
        $this->storeRepository->flush();

        $this->productRepository->saveWithId(Product::factory('ean-1', 'Red square', 'red-square.png', 100));
        $this->productRepository->saveWithId(Product::factory('ean-2', 'Blue circle', null, 101));
        $this->productRepository->flush();

        // O1: Alpha Store, offer productName overrides product name
        $this->offerRepository->saveWithId(Offer::factory(20, 'EXT-800', 'ean-1', 'Custom Name', 1000, null, true, 100, 0, 800));
        // O2: Alpha Store, no offer productName → falls back to product name; visible=false
        $this->offerRepository->saveWithId(Offer::factory(20, 'EXT-801', 'ean-2', null, 1200, null, false, 101, 0, 801));
        // O3: Beta Store, no productId → productName='' after COALESCE
        $this->offerRepository->saveWithId(Offer::factory(21, 'EXT-802', 'ean-3', null, 800, null, true, null, 0, 802));
        // O4: Beta Store, no offer productName → falls back to product name
        $this->offerRepository->saveWithId(Offer::factory(21, 'EXT-803', 'ean-1', null, 900, null, true, 100, 0, 803));
        $this->offerRepository->flush();
    }
}
